#![no_std]
#![allow(non_upper_case_globals)]
#![allow(non_camel_case_types)]
#![allow(non_snake_case)]

// Include the bindings generated by build.rs
include!(concat!(env!("OUT_DIR"), "/bindings.rs"));

// Export the safe wrapper module.
pub mod wrappers;

// Shared hand-written types and constants (Error, Resolution, status codes,
// plugin types, ...) live in `vl53-8x8-types`. Re-export them here so that
// consumers of this crate keep the same paths they had before the split.
pub use vl53_8x8_types::*;

// The C struct `VL53L8CX_Configuration` does not derive Default.
// We need to implement it manually so that it can be easily initialized.
impl Default for VL53L8CX_Configuration {
    fn default() -> Self {
        // Safe way to create a zero-initialized struct.
        unsafe { core::mem::zeroed() }
    }
}

// --- C Data Arrays ---
// These are compiled into the static library by build.rs and needed by the async driver.
extern "C" {
    pub static VL53L8CX_FIRMWARE: [u8; 86016];
    pub static VL53L8CX_DEFAULT_CONFIGURATION: [u8; 972];
    pub static VL53L8CX_DEFAULT_XTALK: [u8; 776];
    pub static VL53L8CX_GET_NVM_CMD: [u8; 40];
}

// --- MANUAL CONSTANT DEFINITIONS ---
// Bindgen often skips macros with explicit casts (e.g. ((uint8_t)0U)).
// We define them manually here to ensure they are available to the driver.

// --- UI Command Registers ---
pub const VL53L8CX_UI_CMD_STATUS: u16 = 0x2C00;
pub const VL53L8CX_UI_CMD_START: u16 = 0x2C04;
pub const VL53L8CX_UI_CMD_END: u16 = 0x2FFF;

